from IQCommon.generalconf import GeneralConf
CONFIG_PATH = '/home/fly/config/trade_schedule.conf'
class TradeSchedule:
    stock_schedule = {'AM_OPEN': 930, 'BEFORE_TRADING_TIME': 700, 'AM_CLOSE': 1130, 'PM_OPEN': 1300, 'TRADE_DAILY': 1450, 'PM_CLOSE': 1500, 'AFTER_TRADING_TIME': 1530}
    future_schedule = {'AM_OPEN': 900, 'BEFORE_TRADING_TIME': 700, 'AM_CLOSE': 1130, 'PM_OPEN': 1300, 'TRADE_DAILY': 1450, 'PM_CLOSE': 1515, 'AFTER_TRADING_TIME': 1530}
    def __init__(self):
        self.config = GeneralConf(CONFIG_PATH)
        try:
            for option in ('STOCK_SCHEDULE', 'FUTURE_SCHEDULE'):
                items = self.config.getconfigitems(option)
                trade_info = getattr(self, option.lower())
                for k, v in items:
                    k = k.upper()
                    if k in trade_info:
                        trade_info[k] = v
                    continue
        except BaseException as e:
            print(e)
            return None
    def get_trade_time(self, type='stock'):
        option = '%s_schedule' % type
        return getattr(self, option, self.stock_schedule).copy()
trade_schedule = TradeSchedule()
if __name__ == '__main__':
    print(trade_schedule.get_trade_time('stock'))
    print(trade_schedule.get_trade_time('future'))
    print(trade_schedule.get_trade_time('others'))
